// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address caller, uint256 newTime) public {
        vm.assume(caller != address(0));

        uint256 amount = 10 ether;

        newTime = bound(newTime, 1, type(uint64).max);
        vm.warp(newTime);

        vm.deal(caller, amount);

        uint256 beforeBalance = address(c).balance;

        vm.prank(caller);
        (bool ok, ) = address(c).call{value: amount}("0x");
        assertTrue(ok);

        if (block.number % 15 != 0) {
            assertTrue(address(c).balance >= beforeBalance);
        } else {
            assertTrue(address(c).balance == beforeBalance || address(c).balance == 0);
        }
    }
}
